// clang-format on

vector<u64> gen() {
    u64 x = 1;
    vector<u64> ans {1};
    for (u64 i = 1; i <= MOD; i++) {
        x = (x * i) % MOD;
        if (i % BSIZE == 0) {
            dbg(i);
            ans.push_back(x);
        }
    }
    return ans;
}

vector<char> to_bits(const vector<u64>& arr, int w) {
    vector<char> bits;
    for (auto& a : arr) {
        for (int i = 0; i < w; i++) {
            bits.push_back(on(a, i));
        }
    }
    return bits;
}

vector<u64> from_bits(const vector<char>& bits, int w) {
    vector<u64> out;
    for (int i = 0; i + w <= sz(bits); i += w) {
        u64 x = 0;
        for (int j = 0; j < w; j++) {
            x |= u64(bits[i + j]) << j;
        }
        out.push_back(x);
    }
    return out;
}

string write(const vector<u64>& arr) {
    auto bits = to_bits(arr, 32);

    while (sz(bits) % 6) {
        bits.push_back(0);
    }

    string out;
    for (auto& a : from_bits(bits, 6)) {
        out += char('0' + a);
    }

    return out;
}

vector<u64> read(const string& in) {
    vector<u64> uin;
    for (auto& a : in) {
        uin.push_back(a - '0');
    }
    return from_bits(to_bits(uin, 6), 32);
}

vector<u64> vals = read(DATA);

void solve() {
    u64 n;
    cin >> n;
    if (n >= MOD) {
        cout << 0 << endl;
        return;
    }
    u64 bv = n / BSIZE, ans = vals[bv], l = bv * BSIZE + 1, r = n + 1;
    while (l % 8 && l <= n) {
        ans = (ans * l++) % MOD;
    }
    while (r % 8 && l < r) {
        ans = (ans * --r) % MOD;
    }
    u64 bk[8];
    fill(begin(bk), end(bk), 1);
    for (; l < r; l += 8) {
        for (u64 i = 0; i < 8; i++) {
            bk[i] = (bk[i] * (l + i)) % MOD;
        }
    }
    for (auto& a : bk) {
        ans = (ans * a) % MOD;
    }
    cout << ans << endl;
}

int main() {
    cin.tie(nullptr);
    cin.exceptions(ios::failbit);
    ios_base::sync_with_stdio(false);
    int tcs;
    cin >> tcs;
    while (tcs--) {
        solve();
    }
}